javascript(/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    let conditionalParams = {};
    const viewType = event.payload.row.rowData.value.get('resource_type').columnData.value;

    if (viewType == "gen_ai_agent" || viewType == "gen_ai_workflow") {
        conditionalParams = {
            "viewType": viewType
        };
    }
    return {
        route: "results",
        fields: {
            requestId: event.payload.sys_id
        },
        params: conditionalParams,
        redirect: null,
        passiveNavigation: null,
        title: null,
        multiInstField: null,
        targetRoute: null,
        external: null
    };
})

